arguments.command:
python3 -I - <<'EOF'
import csv
rows=list(csv.DictReader(open('logs/recorded_run/metrics.csv')))
keys=['step','critic/score/mean','critic/rewards/mean','actor/entropy','actor/kl_loss','actor/grad_norm','training/rollout_probs_diff_max','training/rollout_probs_diff_mean','training/rollout_actor_probs_pearson_corr','rollout_corr/kl','rollout_corr/chi2_seq','rollout_corr/chi2_token','rollout_corr/log_ppl_abs_diff','rollout_corr/ppl_ratio','response_length/mean','response_length/clip_ratio','response_length/max','perf/time_per_step','val-core/hiyouga/geometry3k/acc/mean@1']
print(' | '.join(k.split('/')[-1][:14] for k in keys))
for r in rows:
    vals=[]
    for k in keys:
        v=r.get(k,'')
        try: vals.append(f'{float(v):.4g}')
        except: vals.append('-')
    print(' | '.join(vals))
EOF

