arguments.command:
python3 -I - <<'PY'
import json,glob,collections
files={int(p.split('/')[-1].split('.')[0]):p for p in glob.glob('logs/recorded_run/validation/*.jsonl')}
d={s:[json.loads(l) for l in open(p)] for s,p in sorted(files.items())}
# try align by gts when unique, else by gts and order of occurrence
for a,b in [(0,20),(0,5),(5,20)]:
    ga=collections.defaultdict(list); gb=collections.defaultdict(list)
    for i,r in enumerate(d[a]): ga[r['gts']].append((i,r))
    for i,r in enumerate(d[b]): gb[r['gts']].append((i,r))
    matched=0; imp=deg=both_r=both_w=0; skipped=0
    for g,la in ga.items():
        lb=gb.get(g,[])
        if len(la)==1 and len(lb)==1:
            matched+=1
            xc=la[0][1]['score']>0.5; yc=lb[0][1]['score']>0.5
            if yc and not xc: imp+=1
            elif xc and not yc: deg+=1
            elif xc: both_r+=1
            else: both_w+=1
        else: skipped+=1
    print(f'{a}->{b}: uniquely matched {matched} gts ({skipped} ambiguous groups); improved {imp}, degraded {deg}, both wrong {both_w}, both right {both_r}')
PY

