import json, collections
base='/workspace/logs/recorded_run/validation/'
def load(step):
    rows=[json.loads(l) for l in open(base+f'{step}.jsonl')]
    return rows
for s in [0,5,10,15,20]:
    rows=load(s)
    n=len(rows); correct=sum(1 for r in rows if r['score']>0.5)
    print(s, n, correct, round(correct/n,4), 'acc-mean', round(sum(r['acc'] for r in rows)/n,6), 'reward-mean', round(sum(r['reward'] for r in rows)/n,6))
# pairing on unique gts
def key(r):
    g=r['gts']
    if isinstance(g,list): return tuple(g)
    return (g,)
maps={}
for s in [0,5,10,15,20]:
    rows=load(s)
    c=collections.Counter(key(r) for r in rows)
    maps[s]={key(r): r for r in rows if c[key(r)]==1}
print('unique gts per eval', {s:len(m) for s,m in maps.items()})
for a,b in [(0,5),(0,20),(5,20),(0,10),(10,20)]:
    common=set(maps[a])&set(maps[b])
    up=sum(1 for k in common if maps[a][k]['score']<0.5<=maps[b][k]['score'])
    dn=sum(1 for k in common if maps[b][k]['score']<0.5<=maps[a][k]['score'])
    both_r=sum(1 for k in common if maps[a][k]['score']>=0.5 and maps[b][k]['score']>=0.5)
    both_w=len(common)-up-dn-both_r
    print(f'{a}->{b}: n={len(common)} up={up} down={dn} both_right={both_r} both_wrong={both_w}')
EOF

